-- Migration 022: Create email_templates table

CREATE TABLE email_templates (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID REFERENCES tenants(id),  -- NULL = default BRTNeura template
  template_type VARCHAR(50) NOT NULL,     -- welcome | registration_confirmation | payment_receipt | recovery_link | waitlist_confirmation | subscription_invoice | trial_expiring | subscription_cancelled
  subject VARCHAR(255) NOT NULL,
  html_body TEXT NOT NULL,
  is_active BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(tenant_id, template_type)
);

CREATE INDEX idx_email_templates_tenant ON email_templates(tenant_id);
CREATE INDEX idx_email_templates_type ON email_templates(template_type);

ALTER TABLE email_templates ENABLE ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation_emails ON email_templates
  USING (tenant_id = (auth.jwt() ->> 'tenant_id')::UUID OR tenant_id IS NULL);

