(NULL, 'welcome', 'Welcome to {{tenant_name}}!', '<!DOCTYPE html><html><head><meta charset="utf-8"><style>body{margin:0;padding:0;font-family:Arial,sans-serif;background:#f5f5f5}.container{max-width:600px;margin:0 auto;background:#fff}.header{background:{{primary_color}};color:#fff;padding:30px;text-align:center}.header img{max-height:50px;margin-bottom:10px}.body{padding:30px}.footer{padding:20px;text-align:center;color:#888;font-size:12px;background:#f9f9f9}</style></head><body><div class="container"><div class="header"><img src="{{tenant_logo_url}}" alt="{{tenant_name}}"><h1>Welcome!</h1></div><div class="body"><p>Hi {{attendee_name}},</p><p>Welcome to <strong>{{tenant_name}}</strong>. Your account has been created successfully.</p><p>You can now access your dashboard and manage your events.</p><p>If you have any questions, reach out to us at <a href="mailto:{{support_email}}">{{support_email}}</a>.</p></div><div class="footer"><p>{{tenant_name}} | <a href="mailto:{{support_email}}">{{support_email}}</a></p></div></div></body></html>'),

(NULL, 'registration_confirmation', 'Registration Confirmed - {{event_name}}', '<!DOCTYPE html><html><head><meta charset="utf-8"><style>body{margin:0;padding:0;font-family:Arial,sans-serif;background:#f5f5f5}.container{max-width:600px;margin:0 auto;background:#fff}.header{background:{{primary_color}};color:#fff;padding:30px;text-align:center}.header img{max-height:50px;margin-bottom:10px}.body{padding:30px}.details{background:#f9f9f9;border-radius:8px;padding:20px;margin:20px 0}.details table{width:100%}.details td{padding:8px 0;border-bottom:1px solid #eee}.details td:first-child{font-weight:bold;color:#555;width:40%}.footer{padding:20px;text-align:center;color:#888;font-size:12px;background:#f9f9f9}</style></head><body><div class="container"><div class="header"><img src="{{tenant_logo_url}}" alt="{{tenant_name}}"><h1>Registration Confirmed!</h1></div><div class="body"><p>Hi {{attendee_name}},</p><p>Your registration for <strong>{{event_name}}</strong> has been confirmed.</p><div class="details"><table><tr><td>Event</td><td>{{event_name}}</td></tr><tr><td>Date</td><td>{{event_date}}</td></tr><tr><td>Venue</td><td>{{event_venue}}</td></tr><tr><td>Pass Type</td><td>{{tier_name}}</td></tr><tr><td>Amount Paid</td><td>INR {{amount}}</td></tr><tr><td>Payment ID</td><td>{{payment_id}}</td></tr></table></div><p>We look forward to seeing you!</p></div><div class="footer"><p>{{tenant_name}} | <a href="mailto:{{support_email}}">{{support_email}}</a></p></div></div></body></html>'),

