(NULL, 'trial_expiring', 'Your Trial Ends in 3 Days', '<!DOCTYPE html><html><head><meta charset="utf-8"><style>body{margin:0;padding:0;font-family:Arial,sans-serif;background:#f5f5f5}.container{max-width:600px;margin:0 auto;background:#fff}.header{background:#f59e0b;color:#fff;padding:30px;text-align:center}.body{padding:30px}.cta{display:inline-block;background:#6366f1;color:#fff;padding:14px 32px;border-radius:8px;text-decoration:none;font-weight:bold;margin:20px 0}.footer{padding:20px;text-align:center;color:#888;font-size:12px;background:#f9f9f9}</style></head><body><div class="container"><div class="header"><h1>Trial Ending Soon</h1></div><div class="body"><p>Hi,</p><p>Your free trial of <strong>{{tenant_name}}</strong> ends in 3 days.</p><p>Upgrade now to keep all your features and data:</p><p style="text-align:center"><a href="{{registration_url}}" class="cta">Upgrade Now</a></p><p>After the trial ends, you will lose access to premium features.</p></div><div class="footer"><p>BRTNeura Registration Platform</p></div></div></body></html>'),

(NULL, 'subscription_cancelled', 'Subscription Cancelled - {{tenant_name}}', '<!DOCTYPE html><html><head><meta charset="utf-8"><style>body{margin:0;padding:0;font-family:Arial,sans-serif;background:#f5f5f5}.container{max-width:600px;margin:0 auto;background:#fff}.header{background:#ef4444;color:#fff;padding:30px;text-align:center}.body{padding:30px}.footer{padding:20px;text-align:center;color:#888;font-size:12px;background:#f9f9f9}</style></head><body><div class="container"><div class="header"><h1>Subscription Cancelled</h1></div><div class="body"><p>Hi,</p><p>Your subscription for <strong>{{tenant_name}}</strong> has been cancelled.</p><p>Your access will continue until the end of the current billing period.</p><p>If you change your mind, you can re-subscribe anytime from your dashboard.</p><p>We''d love to have you back!</p></div><div class="footer"><p>BRTNeura Registration Platform</p></div></div></body></html>');
